import{_ as o,a0 as p,w as a,s as r,ao as u,I as s,x as i,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"如何在 Linux 上管理字體 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上管理字體 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上管理字體 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上管理字體 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180518 How to Manage Fonts in Linux","title":"如何在 Linux 上管理字體","tag":"201812","desc":""},"relativePath":"201812/20180518 How to Manage Fonts in Linux.md","filePath":"[post].md"}'),d={name:"201812/20180518 How to Manage Fonts in Linux.md"};function m(f,t,x,g,T,w){const e=p("Link");return a(),r("div",null,[t[18]||(t[18]=u('<h1 id="如何在-linux-上管理字體" tabindex="-1">如何在 Linux 上管理字體 <a class="header-anchor" href="#如何在-linux-上管理字體" aria-label="Permalink to “如何在 Linux 上管理字體”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_main.jpg?itok=qcJks7-c" alt=""></p><p>我不僅寫技術文檔，還寫小説。並且因為我對 GIMP 等工具感到滿意，所以我也（LCTT 譯註：此處應指使用 GIMP）為自己的書籍創作了封面（併為少數客户做了圖形設計）。藝術創作取決於很多東西，包括字體。</p><p>雖然字體渲染已經在過去的幾年裏取得了長足進步，但它在 Linux 平台上仍是個問題。如果你在 Linux 和 macOS 平台上比較相同字體的外觀，差別是顯而易見的，尤其是你要盯着屏幕一整天的時候。雖然在 Linux 平台上尚未找到完美的字體渲染方案，但開源平台做的很好一件事的就是允許用户輕鬆地管理他們的字體。通過選擇、添加、縮放和調整，你可以在 Linux 平台上相當輕鬆地使用字體。</p><p>此處，我將分享一些這些年來我的一些技巧，可以幫我在 Linux 上擴展“字體能力”。這些技巧將對那些在開源平台上進行藝術創作的人有特別的幫助。因為 Linux 平台上有非常多可用的桌面界面（每種界面以不同的方式處理字體），因此當桌面環境成為字體管理的中心時，我將主要聚焦在 GNOME 和 KDE 上。</p><p>話雖如此，讓我們開始吧。</p><h3 id="添加新字體" tabindex="-1">添加新字體 <a class="header-anchor" href="#添加新字體" aria-label="Permalink to “添加新字體”">​</a></h3><p>在相當長的一段時間裏，我都是一個字體收藏家，甚至有些人會説我有些痴迷。從我使用 Linux 的早期開始，我就總是用相同的方法向我的桌面添加字體。有兩種方法可以做到這一點：</p><ul><li>使字體按用户可用；</li><li>使字體在系統範圍內可用。</li></ul><p>因為我的桌面從沒有其他用户（除了我自己），我只使用了按用户可用的字體設置。然而，我會向你演示如何完成這兩種設置。首先，讓我們來看一下如何向用户添加新字體。你首先要做的是找到字體文件，True Type 字體（TTF）和 Open Type 字體（OTF）都可以添加。我選擇手動添加字體，也就是説，我在 <code>~/</code> 目錄下新建了一個名為 <code>~/.fonts</code> 的隱藏目錄。該操作可由以下命令完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir ~/.fonts</span></span></code></pre></div><p>當此文件夾新建完成，我將所有 TTF 和 OTF 字體文件移動到此文件夾中。也就是説，你在此文件夾中添加的所有字體都可以在已安裝的應用中使用了。但是要記住，這些字體只會對這一個用户可用。</p><p>如果你想要使這個字體集合對所有用户可用，你可以如下操作：</p><ol><li>打開一個終端窗口；</li><li>切換路徑到包含你所有字體的目錄中；</li><li>使用 <code>sudo cp *.ttf *.TTF /usr/share/fonts/truetype/</code> 和 <code>sudo cp *.otf *.OTF /usr/share/fonts/opentype</code> 命令拷貝所有字體。</li></ol><p>當下次用户登錄時，他們就將可以使用所有這些漂亮的字體。</p><h3 id="圖形界面字體管理" tabindex="-1">圖形界面字體管理 <a class="header-anchor" href="#圖形界面字體管理" aria-label="Permalink to “圖形界面字體管理”">​</a></h3><p>在 Linux 上你有許多方式來管理你的字體，如何完成取決於你的桌面環境。讓我們以 KDE 為例。使用以 KDE 作為桌面環境的 Kubuntu 18.04，你能夠找到一個預裝的字體管理工具。打開此工具，你就能輕鬆地添加、移除、啓用或禁用字體（當然也包括獲得所有已安裝字體的詳細信息）。這個工具也能讓你輕鬆地針對每個用户或在系統範圍內添加和刪除字體。假如你想要為用户添加一個特定的字體，你需要下載該字體並打開“字體管理”工具。在此工具中（圖 1），點擊“個人字體”並點擊“+”號添加按鈕。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_1.jpg?itok=7yTTe6o3" alt="添加字體" title="adding fonts"></p><p><em>圖 1: 在 KDE 中添加個人字體。</em></p><p>導航至你的字體路徑，選擇它們，然後點擊打開。你的字體就會被添加進了個人區域，並且立即可用（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_2.jpg?itok=_g0dyVYq" alt="KDE 字體管理" title="KDE Font Manager"></p><p><em>圖 2: 使用 KDE 字體管理添加字體</em></p><p>在 GNOME 中做同樣的事需要安裝一個應用。打開 GNOME 軟件中心或者 Ubuntu 軟件中心（取決於你使用的發行版）並搜索字體管理器。選擇“字體管理器”並點擊安裝按鈕。一但安裝完成，你就可以從桌面菜單中啓動它，然後讓我們安裝個人字體。下面是如何安裝：</p><ol><li>從左側窗格選擇“用户”（圖 3）；</li><li>點擊窗口頂部的 “+” 按鈕；</li><li>瀏覽並選擇已下載的字體；</li><li>點擊“打開”。</li></ol><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_3.jpg?itok=8o884QKs" alt="添加字體" title="Adding fonts "></p><p><em>圖 3: 在 GNOME 中添加字體</em></p><h3 id="調整字體" tabindex="-1">調整字體 <a class="header-anchor" href="#調整字體" aria-label="Permalink to “調整字體”">​</a></h3><p>首先你需要理解 3 個概念：</p><ul><li><strong>字體提示：</strong> 使用數學指令調整字體輪廓顯示，使其與光柵化網格對齊。</li><li><strong>抗鋸齒：</strong> 一種通過使曲線和斜線鋸齒狀邊緣光滑化，提高數字圖像真實性的技術。</li><li><strong>縮放因子：</strong> 一個允許你倍增字體大小的縮放單元。也就是説如果你的字體是 12pt 並且縮放因子為 1，那麼字體大小將會是 12pt。如果你的縮放因子為 2，那麼字體將會是 24pt。</li></ul><p>假設你已經安裝好了你的字體，但它們看起來並不像你想的那麼好。你將如何調整字體的外觀？在 KDE 和 GNOME 中，你都可以做一些調整。在調整字體時需要考慮的一件事是，關於字體的口味是非常主觀的。你也許會發現你只得不停地調整，直到你得到了看起來確實滿意的字體（由你的需求和特殊口味決定）。讓我們先看一下 KDE 下的情況吧。</p><p>打開“系統設置”工具並點擊“字體”。在此節中，你不僅能切換不同字體，你也能夠啓用或配置抗鋸齒或啓用字體縮放因子（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_4.jpg?itok=QJpPzFED" alt="配置字體" title="Configuring fonts"></p><p><em>圖 4: 在 KDE 中配置字體</em></p><p>要配置抗鋸齒，在下拉菜單中選擇“啓用”並點擊“配置”。在結果窗口中（圖 5），你可以配置“排除範圍”、“子像素渲染類型”和“提示類型”。</p><p>一但你做了更改，點擊“應用”。重啓所有正在運行的程序，然後新的設置就會生效。</p><p>要在 GNOME 中這麼做，你需要安裝“字體管理器”或 GNOME Tweaks。在此處，GNOME Tweaks 是更好的工具。如果你打開 GNOME Dash 菜單但沒有找到 Tweaks，打開 GNOME “軟件”（或 Ubuntu “軟件”）並安裝 GNOME Tweaks。安裝完畢，打開並點擊“字體”，此處你可以配置提示、抗鋸齒和縮放因子（圖 6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fonts_6.jpg?itok=4cQeIW9C" alt="調整字體" title="Tweaking fonts"></p><p><em>圖 6: 在 GNOME 中調整字體</em></p><h3 id="美化你的字體" tabindex="-1">美化你的字體 <a class="header-anchor" href="#美化你的字體" aria-label="Permalink to “美化你的字體”">​</a></h3><p>以上便是使你的 Linux 字體儘可能漂亮的要旨。你可能得不到像 macOS 那樣渲染的字體，但你一定可以提升字體外觀。最後，你選擇的字體會很大程度地影響視覺效果，因此請確保你安裝的字體是乾淨並且完整適配的，否則你將輸掉這次對抗。</p>',40)),s("p",null,[t[1]||(t[1]=i("通過 The Linux Foundation 和 edX 平台的免費課程 ",-1)),n(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...t[0]||(t[0]=[i("初識 Linux",-1)])]),_:1}),t[2]||(t[2]=i(" 瞭解更多關於 Linux 的信息。",-1))]),t[19]||(t[19]=s("hr",null,null,-1)),s("p",null,[t[4]||(t[4]=i("via: ",-1)),n(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/5/how-manage-fonts-linux"},{default:l(()=>[...t[3]||(t[3]=[i("https://www.linux.com/learn/intro-to-linux/2018/5/how-manage-fonts-linux",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=i("作者：",-1)),n(e,{href:"https://www.linux.com/users/jlwallen"},{default:l(()=>[...t[5]||(t[5]=[i("Jack Wallen",-1)])]),_:1}),t[10]||(t[10]=i(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[6]||(t[6]=[i("lujun9972",-1)])]),_:1}),t[11]||(t[11]=i(" 譯者：",-1)),n(e,{href:"https://github.com/cycoe"},{default:l(()=>[...t[7]||(t[7]=[i("cycoe",-1)])]),_:1}),t[12]||(t[12]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[i("LCTT",-1)])]),_:1}),t[16]||(t[16]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[i("Linux中國",-1)])]),_:1}),t[17]||(t[17]=i(" 榮譽推出",-1))])])}const b=o(d,[["render",m]]);export{k as __pageData,b as default};
